async function ownedScenario(t,run){
 const cleanup=[],errors=[];
 try{await run({signal:t.signal,after:close=>cleanup.push(close),diagnostic:value=>t.diagnostic(value)});}catch(error){errors.push(error);}
 // Node same-kind hooks run in registration order; stop each owned app before its fixture hook drops the schema.
 for(const close of cleanup)try{await close();}catch(error){errors.push(error);}
 if(errors.length)throw errors.length===1?errors[0]:new AggregateError(errors,'Recovery scenario and owned cleanup failed');
}
